SELECT 'core-2026-09-v4','have-got','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"have-got","title":"Have got","level":"A1","order":9,"summary":"Talk about possessions, characteristics and present arrangements with have got.","learningGoals":["Have or has","Negative and question forms","Short answers and time"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"Have or has","explanation":"Use have got with I, you, we and they; use has got with he, she, it or a singular noun.","examples":["I have got a warm coat.","The cabin has got two bedrooms."]},{"title":"Negative and question forms","explanation":"Put not after have or has. In questions, move have or has before the subject and keep got after it.","examples":["We have not got a spare wheel.","Has the flat got a balcony?"]},{"title":"Short answers and time","explanation":"Short answers keep have or has but leave out got. This possession pattern describes the present; use had for past possession.","examples":["Yes, it has.","They had a garden before they moved."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-have-got"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["Have got is common, especially in spoken British English, for current possessions, relationships and characteristics. In this pattern have or has acts as the question-forming auxiliary. It is not the same as every use of ordinary have, nor does it normally describe a repeated action."],"rules":[{"title":"Have or has","explanation":"Use have got with I, you, we and they; use has got with he, she, it or a singular noun.","examples":["I have got a warm coat.","The cabin has got two bedrooms.","She **has got** three cousins."],"pattern":"I **have got** / She **has got**","paragraphs":["Have goes with I, you, we and they; has goes with he, she, it and a singular noun. The possessed object does not control the verb: She has got two keys still uses has because she is singular. Contractions such as I’ve got and she’s got are common."],"id":"have-got-foundation-1","domain":"verbs","referenceIds":["bc-have-got"],"readingVersion":"foundations-2026-09-v2"},{"title":"Negative and question forms","explanation":"Put not after have or has. In questions, move have or has before the subject and keep got after it.","examples":["We have not got a spare wheel.","Has the flat got a balcony?","**Have** you **got** a spare charger?"],"pattern":"**Has** she **got** a key? / She **has not got** a key.","paragraphs":["To make a question, move have/has before the subject and retain got. To make a negative, put not after have/has. Ordinary have can instead use do-support: Does she have a key? Both systems are valid, but do not mix them into Does she have got a key?"],"id":"have-got-foundation-2","domain":"verbs","referenceIds":["bc-have-got"],"readingVersion":"foundations-2026-09-v2"},{"title":"Short answers and time","explanation":"Short answers keep have or has but leave out got. This possession pattern describes the present; use had for past possession.","examples":["Yes, it has.","They had a garden before they moved.","They **had** a garden before they moved."],"pattern":"Yes, she **has**. / No, she **has not**.","paragraphs":["Short answers omit got and keep the appropriate auxiliary. This possession construction normally refers to now. For earlier possession, use had: I had a bicycle as a child. Future possession commonly uses will have."],"id":"have-got-foundation-3","domain":"verbs","referenceIds":["bc-have-got"],"readingVersion":"foundations-2026-09-v2"},{"title":"Contrasts and edge cases","explanation":"Have got to can express obligation and is a separate pattern: I’ve got to leave. Ordinary have also appears in activities such as have breakfast; possession-style have got is not a universal replacement. Have you got ...? and Do you have ...? are both standard questions.","examples":["She **has got** three cousins.","**Have** you **got** a spare charger?","They **had** a garden before they moved."],"id":"have-got-foundation-4","domain":"verbs","referenceIds":["bc-have-got"],"readingVersion":"foundations-2026-09-v2"}],"recap":["I **have got** / She **has got**","**Has** she **got** a key? / She **has not got** a key.","Yes, she **has**. / No, she **has not**."],"readingVersion":"core-2026-09-v4"},"stage":"1 · Sentence foundations","prerequisites":["there-is-there-are"],"readingReferenceIds":["bc-have-got"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='have-got'
